import urllib.request
import re
from html.parser import HTMLParser

class NavFooterParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.in_nav = False
        self.in_footer = False
        self.nav_links = []
        self.footer_links = []
        self.current_a = None
        self.current_text = []

    def handle_starttag(self, tag, attrs):
        attr_dict = dict(attrs)
        c = attr_dict.get("class", "")
        i = attr_dict.get("id", "")

        if tag == "nav" or "nav" in c or "header" in c or "megaMenu" in i or "top-bar" in i:
            self.in_nav = True
        if tag == "footer" or "footer" in c or "footerWrap" in i:
            self.in_footer = True

        if tag == "a":
            self.current_a = attr_dict.get("href", "")
            self.current_text = []

    def handle_endtag(self, tag):
        if tag == "a" and self.current_a:
            text = " ".join(self.current_text).strip()
            if text:
                if self.in_footer:
                    self.footer_links.append((text, self.current_a))
                elif self.in_nav:
                    self.nav_links.append((text, self.current_a))
            self.current_a = None
            self.current_text = []

        if tag in ["nav", "header"]:
            self.in_nav = False
        if tag == "footer":
            self.in_footer = False

    def handle_data(self, data):
        if self.current_a:
            self.current_text.append(data.strip())

